```python
def get_openapi_security_definitions(
    flat_dependant: Dependant,
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    security_definitions = {}
    operation_security = []
    for security_requirement in flat_dependant.security_requirements:
        security_definition = jsonable_encoder(
            security_requirement.security_scheme.model,
            by_alias=True,
            exclude_none=True,
        )
        security_name = security_requirement.security_scheme.scheme_name
        if security_name in security_definitions:
            if security_definition.get("type") == "oauth2":
                # Merge scopes for oauth2
                existing_definition = security_definitions[security_name]
                if existing_definition.get("type") == "oauth2":
                    # Merge flows
                    for flow_type, flow_details in security_definition.get("flows", {}).items():
                        if flow_type in existing_definition.get("flows", {}):
                            existing_scopes = set(existing_definition["flows"][flow_type].get("scopes", []))
                            new_scopes = set(flow_details.get("scopes", []))
                            existing_definition["flows"][flow_type]["scopes"] = sorted(list(existing_scopes | new_scopes))
                        else:
                            existing_definition["flows"].setdefault("flows", {})[flow_type] = flow_details
                else:
                    security_definitions[security_name] = security_definition
            else:
                security_definitions[security_name] = security_definition
        else:
            security_definitions[security_name] = security_definition
        operation_security.append({security_name: security_requirement.scopes})
    return security_definitions, operation_security
